package com.smartcanteen.config;
import com.smartcanteen.domain.User; import com.smartcanteen.repo.UserRepository; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.nio.charset.StandardCharsets; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filterChain(HttpSecurity http, JwtFilter jwt) throws Exception { return http.csrf(x->x.disable()).cors(c->c.configurationSource(r->{var cfg=new CorsConfiguration();cfg.setAllowedOrigins(java.util.List.of("http://localhost:5173"));cfg.setAllowedMethods(java.util.List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));cfg.setAllowedHeaders(java.util.List.of("*"));return cfg;})).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(x->x.requestMatchers("/api/auth/**","/h2-console/**").permitAll().anyRequest().authenticated()).headers(x->x.frameOptions(f->f.sameOrigin())).addFilterBefore(jwt, UsernamePasswordAuthenticationFilter.class).build(); }
 @Bean SecretKey secretKey(@Value("${app.jwt-secret}") String value){return Keys.hmacShaKeyFor(value.getBytes(StandardCharsets.UTF_8));}
 @Bean JwtFilter jwtFilter(UserRepository users, SecretKey key){return new JwtFilter(users,key);}
 static class JwtFilter extends OncePerRequestFilter { final UserRepository users; final SecretKey key; JwtFilter(UserRepository users,SecretKey key){this.users=users;this.key=key;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload().getSubject();users.findByEmail(email).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.email,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.role)))));}catch(Exception ignored){} chain.doFilter(req,res);} }
}
